    table: { head: ["", "machen", "wohnen"], rows: [["ich", "mach**e**", "wohn**e**"], ["du", "mach**st**", "wohn**st**"], ["er/sie/es", "mach**t**", "wohn**t**"], ["wir", "mach**en**", "wohn**en**"], ["ihr", "mach**t**", "wohn**t**"], ["sie/Sie", "mach**en**", "wohn**en**"]] },
    ex: [["Ich [[mache]] heute Sport.", "I'm doing sport today."], ["Was [[machst]] du am Wochenende?", "What are you doing at the weekend?"], ["Wir [[wohnen]] in Berlin.", "We live in Berlin."]],
